import React from 'react';

import * as L from 'leaflet';

import { watermarkToMap } from '@apps/Routes/@helpers/addToMap.helper';
import { decodePolyline } from '@helpers/gpsHelper';
import { getDefaultTileLayer, getMap, setDefaultMapView } from '@helpers/leafletHelper';

import { IStatYearTotalTrack } from './statYear.types';

interface IStatYearMapProps extends React.HTMLAttributes<HTMLDivElement> {
  tracks: IStatYearTotalTrack[];
  noControls?: boolean;
}

const StatYearMap: React.FC<IStatYearMapProps> = ({ tracks, noControls = false, ...rest }) => {
  const mapContainerRef = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);

  React.useEffect(() => {
    if (!mapContainerRef.current) {
      return;
    }
    mapRef.current = getMap(mapContainerRef.current, {
      fullscreenControl: !noControls,
      zoomControl: false,
    });

    setDefaultMapView(mapRef.current);
    watermarkToMap(mapRef.current);

    getDefaultTileLayer().addTo(mapRef.current);
  }, [mapContainerRef]);

  React.useEffect(() => {
    if (!mapContainerRef.current || !mapRef.current) {
      return;
    }
    const tracksFeatureGroup = new L.FeatureGroup();
    tracksFeatureGroup.addTo(mapRef.current);

    const polylines: L.Polyline[] = [];

    tracks.forEach(({ id, trackdata }) => {
      const coords = decodePolyline(trackdata).map(([la, lo]) => [la, lo]);
      const pl = new L.Polyline(coords as L.LatLngExpression[], {
        color: '#fe4542',
        weight: 5,
        opacity: 0.5,
        // dashArray:[5,5]
      });

      pl.addTo(tracksFeatureGroup);
      pl.bindTooltip(id);
      polylines.push(pl);

      return () => {
        polylines.forEach((item) => {
          mapRef.current?.removeLayer(item);
        });
      };
    });

    setTimeout(() => {
      const bounds = tracksFeatureGroup.getBounds();
      if (bounds.isValid()) {
        mapRef.current && mapRef.current.fitBounds(bounds);
      }
    }, 0);
  }, [tracks]);

  return <div ref={mapContainerRef} {...rest} />;
};

export default StatYearMap;
