import React from 'react';

import PohAva, { IPohAvaProps } from '@ui-kit/Ava';

import { getObstacleTypeName } from '../../@resources/obstacles.resource';
import { ObstacleType } from '../../@types/obstacles.types';
import { ObstacleIcon } from '../ObstacleIcon/ObstacleIcon';

interface IObstacleAvaProps extends IPohAvaProps {
  type: ObstacleType;
}

const ObstacleAva: React.FC<IObstacleAvaProps> = ({ type, ...rest }) => {
  return (
    <PohAva
      {...rest}
      colorize
      alt={getObstacleTypeName(type)}
      icon={<ObstacleIcon type={type} />}
    />
  );
};

export default ObstacleAva;
